<?php
namespace App\Http\Controllers\Api; use App\Http\Requests\Api\PayrollRequest; use App\Models\Payroll; use App\Traits\ApiResponseTrait; use Illuminate\Http\Request;
class PayrollController {use ApiResponseTrait; public function index(Request $r){return $this->success(Payroll::with('employee')->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->period_year,fn($q,$v)=>$q->where('period_year',$v))->latest()->paginate(15));} public function store(PayrollRequest $r){$d=$r->validated();$d['status']=$d['status']??'generated';$d['base_salary']=$d['base_salary']??optional(\App\Models\Employee::find($d['employee_id']))->base_salary??0;$d['gross_pay']=$d['base_salary']+($d['overtime_pay']??0)+($d['bonuses']??0)+($d['benefits_in_kind']??0);$d['social_security_employee']=round($d['gross_pay']*.01,2);$d['taxes']=round($d['gross_pay']*.05,2);$d['net_pay']=$d['gross_pay']-$d['social_security_employee']-$d['taxes'];$payroll=Payroll::create($d); $payroll->employee?->user?->notify(new \App\Notifications\PayrollStatusNotification($payroll->id,'générée',(float)$payroll->net_pay)); return $this->success($payroll,'Payroll generated',201);} public function show(Payroll $payroll){return $this->success($payroll->load('employee'));} public function validatePayroll(Payroll $p){fwrite(STDERR,"DEBUG-VPA-IN: id=".var_export($p->getKey(),true)." exists=".var_export($p->exists,true)." attrs=".json_encode(array_keys($p->getAttributes()))."\n");$p->update(['status'=>'validated']);fwrite(STDERR,"DEBUG-VPA-UPD: status=".var_export($p->status,true)." dirty=".json_encode($p->getDirty())."\n");$f=$p->fresh();fwrite(STDERR,"DEBUG-VPA-FRESH: ".var_export($f!==null,true)."\n");return $this->success($f);} public function pay(Request $r,Payroll $p){fwrite(STDERR,"DEBUG-PAY-IN: id=".var_export($p->getKey(),true)." exists=".var_export($p->exists,true)."\n");$p->update(['status'=>'paid','payment_date'=>$r->input('payment_date',now()),'payment_reference'=>$r->input('payment_reference')]);$p->employee?->user?->notify(new \App\Notifications\PayrollStatusNotification($p->id,'payée',(float)$p->net_pay));return $this->success($p->fresh());} public function employee(int $employee){return $this->success(Payroll::where('employee_id',$employee)->latest()->paginate(15));} public function export(Request $r){$rows=Payroll::with('employee')->when($r->period_year,fn($q,$v)=>$q->where('period_year',$v))->when($r->period_month,fn($q,$v)=>$q->where('period_month',$v))->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['employee_id','employee','month','year','gross_pay','net_pay','status']);foreach($rows as $p)fputcsv($out,[$p->employee_id,$p->employee?->first_name.' '.$p->employee?->last_name,$p->period_month,$p->period_year,$p->gross_pay,$p->net_pay,$p->status]);fclose($out);},'payroll-export.csv',['Content-Type'=>'text/csv']);}}
